# lcmv_xtra/source_estimation_epochs_native.py

import mne
import json
import logging
import numpy as np
from pathlib import Path
from typing import Dict, Tuple, Optional, List

# Import shared utilities from the standard epochs module
from .source_estimation_epochs import (
    load_epochs, _setup_logger
)

mne.set_log_level('warning')

def validate_native_anatomy(subject_id: str, subjects_dir: Path) -> Tuple[Path, Path]:
    """Validate native subject BEM and source space generated by the anatomy pipeline."""
    subj_dir = Path(subjects_dir) / subject_id
    
    bem_file = subj_dir / 'bem' / f'{subject_id}-bem-sol.fif'
    if not bem_file.exists():
        bem_file = subj_dir / 'bem' / f'{subject_id}-5120-5120-5120-bem-sol.fif'
        
    src_file = subj_dir / f'{subject_id}-vol-5mm-src.fif'
    
    if not (bem_file.exists() and src_file.exists()):
        raise FileNotFoundError(
            f"Missing native anatomy files for {subject_id} in {subj_dir}. "
            "Please run the native anatomy pipeline first."
        )
    return bem_file, src_file

def _run_coregistration(info: mne.Info, ch_pos: Dict, subject: str,
                        subjects_dir: Path, trans_file: Path,
                        logger: logging.Logger) -> Tuple[mne.transforms.Transform, Dict]:
    """Run enhanced coregistration with ICP and outlier removal."""
    log = logger or logging.getLogger(__name__)
    
    # ========================================================================
    # THE ONLY CHANGE: Explicitly point to the native watershed head surface
    # ========================================================================
    native_head_surf = Path(subjects_dir) / subject / "bem" / f"{subject}-head.fif"
    if not native_head_surf.exists():
        raise FileNotFoundError(
            f"Native head surface not found: {native_head_surf}\n"
            "Ensure 02_generate_bem_and_source_space.py has completed successfully."
        )
    # ========================================================================

    coreg = mne.coreg.Coregistration(
        info, 
        subject=subject, 
        subjects_dir=subjects_dir,
        fiducials={'nasion': ch_pos['FidNz'], 'lpa': ch_pos['FidT9'], 'rpa': ch_pos['FidT10']},
        head_surface=str(native_head_surf)  # <--- PASS THE NATIVE SURFACE HERE
    )
    
    # Everything below remains EXACTLY the same as your original fsaverage version
    coreg.fit_fiducials(verbose=False)
    coreg.fit_icp(n_iterations=6, nasion_weight=2.0, verbose=False)

    dists = coreg.compute_dig_mri_distances()
    if np.sum(dists > 5.0 / 1000) > 0:
        coreg.omit_head_shape_points(distance=5.0 / 1000)

    coreg.fit_icp(n_iterations=20, nasion_weight=10.0, verbose=False)
    trans = coreg.trans
    mne.write_trans(trans_file, trans, overwrite=True)

    dists = coreg.compute_dig_mri_distances() * 1000
    mean_err, median_err, max_err = np.mean(dists), np.median(dists), np.max(dists)
    log.info(f"Coreg error (mm) - Mean: {mean_err:.2f}, Median: {median_err:.2f}, Max: {max_err:.2f}")

    if mean_err > 5.0:
        raise RuntimeError(f"Mean error {mean_err:.2f}mm exceeds 5mm threshold.")

    return trans, {'mean': mean_err, 'median': median_err, 'max': max_err}
                            
def lcmv_beamformer_epochs_native(
    epochs: mne.Epochs,
    ch_pos: Dict,
    subjects_dir: Path,
    output_dir: Path,
    subject_id: str,
    task: str,
    reg: float = 0.05,
    mindist: float = 2.0, 
    n_jobs: int = 1,
    verbose: bool = False,
    noise_cov_method: str = 'shrunk',
    baseline_tmin: Optional[float] = None,
    baseline_tmax: Optional[float] = 0.0,
    data_cov_tmin: Optional[float] = None,
    data_cov_tmax: Optional[float] = None,
    compute_noise_cov: bool = True,
    coregister: bool = True,
) -> Dict:
    """
    Run epoch-based LCMV source estimation purely in the SUBJECT'S NATIVE SPACE.
    Computes the forward model and beamformer filters in native space for 
    biophysical accuracy. Saves un-morphed native STCs.
    """
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    log = _setup_logger(subject_id, task, output_dir, verbose)
    
    log.info(f"{'='*60}")
    log.info(f"PURE NATIVE LCMV Epoch Source Estimation: {subject_id} - {task}")
    log.info(f"{'='*60}")

    native_bem_file, native_src_file = validate_native_anatomy(subject_id, subjects_dir)
    src_native = mne.read_source_spaces(native_src_file)
    bem_native = mne.read_bem_solution(native_bem_file)

    trans_file = output_dir / f'{subject_id}-trans.fif'
    
    if coregister:
        log.info("Running ICP coregistration to native MRI...")
        trans, coreg_errors = _run_coregistration(
            epochs.info, ch_pos, subject_id, subjects_dir, trans_file, log
        )
    else:
        log.info("Skipping coregistration (coregister=False).")
        log.info("Assuming sensor positions in .fif are already aligned to the native MRI space.")
        trans = mne.transforms.Transform('head', 'mri')
        mne.write_trans(trans_file, trans, overwrite=True)
        coreg_errors = {'mean': 0.0, 'median': 0.0, 'max': 0.0}

    log.info(f"Computing native forward solution (mindist={mindist}mm)...")
    fwd = mne.make_forward_solution(
        epochs.info, trans=trans, src=src_native, bem=bem_native, 
        eeg=True, mindist=mindist, n_jobs=n_jobs  # <--- CHANGED: Use parameter instead of hardcoded 5.0/2.0
    )

    epochs_eeg = epochs.copy().pick('eeg')

    log.info(f"Computing DATA covariance from window [{data_cov_tmin}, {data_cov_tmax}]s...")
    data_cov = mne.compute_covariance(
        epochs_eeg, tmin=data_cov_tmin, tmax=data_cov_tmax,
        method='oas', rank=None, n_jobs=n_jobs, verbose=False
    )
    
    noise_cov = None
    if compute_noise_cov:
        log.info(f"Computing NOISE covariance from baseline [{baseline_tmin}, {baseline_tmax}]s...")
        noise_cov = mne.compute_covariance(
            epochs_eeg, tmin=baseline_tmin, tmax=baseline_tmax,
            method=noise_cov_method, rank=None, n_jobs=n_jobs, verbose=False
        )

    log.info("Computing LCMV filters in native space...")
    filters = mne.beamformer.make_lcmv(
        info=epochs.info, forward=fwd,
        data_cov=data_cov, noise_cov=noise_cov, reg=reg,
        pick_ori='max-power', weight_norm='unit-noise-gain',
        reduce_rank=True, rank=None, verbose=False
    )

    log.info("Applying LCMV beamformer to single-trial epochs (native space)...")
    stcs_native: List[mne.VolSourceEstimate] = mne.beamformer.apply_lcmv_epochs(
        epochs=epochs, filters=filters
    )

    native_dir = output_dir / "native_stcs"
    native_dir.mkdir(parents=True, exist_ok=True)
    log.info(f"Saving {len(stcs_native)} UN-MORPHED native epoch STCs to {native_dir}...")
    for i, stc_nat in enumerate(stcs_native):
        native_file = native_dir / f'source_estimate_LCMV_epoch_{i:03d}_native.h5'
        stc_nat.save(native_file, ftype='h5', overwrite=True)

    metadata = {
        'subject_id': subject_id,
        'task': task,
        'space': 'pure_native_unmorphed',
        'coregistration_applied': coregister,
        'forward_mindist_mm': float(mindist),  # <--- ADDED: Track mindist in metadata
        'sfreq_hz': float(epochs.info['sfreq']),
        'epoch_tmin': float(epochs.tmin),
        'epoch_tmax': float(epochs.tmax),
        'n_epochs': len(stcs_native),
        'n_sources': int(stcs_native[0].data.shape[0]),
        'coreg_mean_error_mm': float(coreg_errors['mean']),
        'regularization': reg,
        'data_covariance_window': [data_cov_tmin, data_cov_tmax],
        'compute_noise_covariance': compute_noise_cov,
        'noise_baseline_window': [baseline_tmin, baseline_tmax] if compute_noise_cov else None,
        'weight_normalization': 'unit-noise-gain',
        'covariance_mode': 'separate',
        'subject_output': str(output_dir),
        'native_stcs_dir': str(native_dir),
    }
    with open(output_dir / 'pipeline_metadata.json', 'w') as f:
        json.dump(metadata, f, indent=2)

    log.info(f"Pure native epoch source estimation complete: {output_dir}")
    log.info(f"{'='*60}\n")
    return metadata

def execute_source_estimation_epochs_native(
    project_base: Path,
    subject_id: str,
    task: str,
    epochs_file_path: str,
    subjects_dir: Path,
    reg: float = 0.05,
    mindist: float = 2.0,  # <--- ADDED: Expose mindist in orchestrator
    n_jobs: int = 1,
    verbose: bool = False,
    noise_cov_method: str = 'shrunk',
    baseline_tmin: Optional[float] = None,
    baseline_tmax: Optional[float] = 0.0,
    data_cov_tmin: Optional[float] = None,
    data_cov_tmax: Optional[float] = None,
    compute_noise_cov: bool = True,
    coregister: bool = True,
) -> Dict:
    """High-level orchestrator for pure native epoch-based LCMV source estimation."""
    import lcmv_xtra
    
    project_base = Path(project_base)
    package_dir = Path(lcmv_xtra.__file__).parent
    gpsc_full_path = package_dir / 'data' / 'bel_280' / 'ghw280_from_egig.gpsc'

    epochs_full_path = project_base / epochs_file_path
    output_dir = project_base / 'derivatives' / 'lcmv' / f'{subject_id}_{task}_epochs_native'

    epochs, ch_pos = load_epochs(
        epochs_file_path=epochs_full_path, gpsc_file_path=gpsc_full_path,
        subject_id=subject_id, logger=None
    )

    return lcmv_beamformer_epochs_native(
        epochs=epochs, ch_pos=ch_pos, 
        subjects_dir=subjects_dir, 
        output_dir=output_dir, subject_id=subject_id, task=task,
        reg=reg, mindist=mindist, n_jobs=n_jobs, verbose=verbose, 
        noise_cov_method=noise_cov_method,
        baseline_tmin=baseline_tmin, baseline_tmax=baseline_tmax,
        data_cov_tmin=data_cov_tmin, data_cov_tmax=data_cov_tmax,
        compute_noise_cov=compute_noise_cov,
        coregister=coregister,
    )
